changeSet.sql:
DECLARE @qId BIGINT, @q2Id BIGINT;
DECLARE @optId BIGINT;
DECLARE @studentAttemptId BIGINT;

SELECT @qId = id FROM question WHERE prompt = 'Define the term "Atomicity" in the context of database transactions.';
SELECT @q2Id = id FROM question WHERE prompt = 'True or False: A primary key can contain NULL values.';

SELECT @optId = id FROM answer_option WHERE question_id = @q2Id AND content = 'False';

SELECT TOP 1 @studentAttemptId = id FROM student_attempt ORDER BY id DESC;

INSERT INTO answer_attempt (answer_option_id, question_id, student_attempt_id, provided_text, is_answer_correct)
VALUES
    (NULL, @qId, @studentAttemptId, 'Answer for the question.', 1),
    (@optId, NULL, @studentAttemptId, NULL, 1);
